import os
import hmac
import hashlib
import string
import unicodedata
from flask import Flask, request, session, abort, jsonify
from functools import wraps

app = Flask(__name__)
app.secret_key = os.urandom(32)

# Simulated user store with proper password hashing
SALTS = {}
PASSWORD_HASHES = {}

def _hash_pw(password, salt=None):
    if salt is None:
        salt = os.urandom(16)
    h = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 200000)
    return salt, h

def _init_users():
    for user, pw, role in [('admin','adm1n_s3cr3t','admin'),('analyst','4nalyst!','analyst'),('viewer','v13w3r','viewer')]:
        salt, h = _hash_pw(pw)
        SALTS[user] = salt
        PASSWORD_HASHES[user] = h

_init_users()

ROLES = {'admin': {'view','analyze','export'}, 'analyst': {'view','analyze','export'}, 'viewer': {'view'}}

def require_perm(perm):
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            if 'user' not in session:
                abort(401)
            role = session.get('role', 'viewer')
            if perm not in ROLES.get(role, set()):
                abort(403)
            return f(*args, **kwargs)
        return wrapper
    return decorator

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username', '')
    password = request.form.get('password', '')
    if username not in SALTS:
        # Constant-time comparison against dummy to prevent timing
        _hash_pw(password, b'\x00' * 16)
        abort(401)
    salt = SALTS[username]
    _, h = _hash_pw(password, salt)
    if not hmac.compare_digest(h, PASSWORD_HASHES[username]):
        abort(401)
    session['user'] = username
    session['role'] = 'admin' if username == 'admin' else ('analyst' if username == 'analyst' else 'viewer')
    return jsonify({'status': 'ok'})


