class FieldValidator:
    """Validates format string fields to prevent attribute traversal.

    Security model: Only allow simple field names from a whitelist.
    Reject any field that contains attribute access (.), indexing ([),
    or conversion (!) operators.
    """

    ALLOWED_FIELDS = frozenset(['title', 'author', 'date', 'summary', 'row_count', 'status'])
    DANGEROUS_CHARS = frozenset('.[]!\\"\'')

    @classmethod
    def validate_format_string(cls, fmt_str):
        """Parse and validate a format string.

        Returns True if safe, raises ValueError if dangerous.
        Uses string.Formatter().parse() for robust parsing.
        Normalizes FIRST to prevent unicode bypass.
        """
        # CRITICAL: Normalize BEFORE validation to prevent unicode bypass
        normalized = unicodedata.normalize('NFKC', fmt_str)

        formatter = string.Formatter()
        try:
            parsed = list(formatter.parse(normalized))
        except (ValueError, KeyError):
            raise ValueError("Invalid format string syntax")

        for literal_text, field_name, format_spec, conversion in parsed:
            if field_name is None:
                continue

            # Check for dangerous characters in the raw field name
            for ch in cls.DANGEROUS_CHARS:
                if ch in field_name:
                    raise ValueError(f"Dangerous character '{ch}' in field name")

            # Verify field is in whitelist
            if field_name not in cls.ALLOWED_FIELDS:
                raise ValueError(f"Field '{field_name}' not in allowed set")

            # Reject conversions
            if conversion:
                raise ValueError("Conversions not allowed")

            # Validate format_spec doesn't contain nested fields
            if format_spec and ('{' in format_spec or '}' in format_spec):
                raise ValueError("Nested format specs not allowed")

        return True


def normalize_and_render(fmt_str, mapping):
    """Normalize unicode in format string then render.

    We normalize to NFKC to ensure consistent representation
    of characters before rendering.
    """
    # Normalize to canonical form for consistent storage/display
    normalized = unicodedata.normalize('NFKC', fmt_str)
    return normalized.format_map(mapping)


def build_report(title, author, date, summary, row_count, status, user_format):
    """Build a formatted report using validated user format string."""

    # Validate the user-supplied format string (normalizes internally before checking)
    FieldValidator.validate_format_string(user_format)

    # Build the data mapping with only safe string values
    data_mapping = {
        'title': str(title),
        'author': str(author),
        'date': str(date),
        'summary': str(summary),
        'row_count': str(row_count),
        'status': str(status),
    }

    # Render with normalization for proper unicode display
    return normalize_and_render(user_format, data_mapping)


@app.route('/export', methods=['POST'])
@require_perm('export')
def export_report():
    title = request.form.get('title', 'Untitled')
    author = session.get('user', 'unknown')
    date = request.form.get('date', '2024-01-01')
    summary = request.form.get('summary', '')
    row_count = request.form.get('row_count', '0')
    status = request.form.get('status', 'draft')
    user_format = request.form.get('format', '{title} by {author} - {summary}')

    try:
        result = build_report(title, author, date, summary, row_count, status, user_format)
        return jsonify({'report': result})
    except ValueError as e:
        return jsonify({'error': str(e)}), 400


